def get_week_template_component_rows(template_id):
    ensure_week_template_tables()
    return fetch_all(
        f'select * from {table_name(WEEK_TEMPLATE_COMPONENTS_TABLE)} '
        f'where week_template_id = %s order by display_order asc',
        [template_id],
    )

